package com.keevo.identity.onboarding.adapter.out.persistence;

import jakarta.persistence.*;

import java.time.Instant;
import java.util.UUID;

/**
 * CategoryJpaEntity — JPA entity mapping to the {@code categories} table in the tenant schema.
 *
 * <p>The table is created by {@link com.keevo.shared.infrastructure.persistence.TenantSchemaProvisioner}
 * (DDL_CATEGORIES constant) within each tenant's PostgreSQL schema.
 *
 * <p>UUID is generated by Hibernate (IETF RFC 4122 UUID v4) — NOT passed from the caller.
 * This ensures Hibernate always uses persist (not merge) on new entities.
 */
@Entity
@Table(name = "categories")
public class CategoryJpaEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id;

    @Column(name = "name", nullable = false, length = 100)
    private String name;

    @Column(name = "parent_id")
    private UUID parentId;

    @Column(name = "is_active", nullable = false)
    private boolean isActive;

    @Column(name = "is_custom", nullable = false)
    private boolean isCustom;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    // ── JPA requires no-arg constructor ───────────────────────────────────────
    protected CategoryJpaEntity() {}

    /** Factory constructor — id is intentionally omitted; Hibernate generates it. */
    public CategoryJpaEntity(String name, UUID parentId,
                              boolean isActive, boolean isCustom,
                              Instant createdAt, Instant updatedAt) {
        this.name = name;
        this.parentId = parentId;
        this.isActive = isActive;
        this.isCustom = isCustom;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
    }

    // ── Accessors ────────────────────────────────────────────────────────────

    public UUID getId() { return id; }
    public String getName() { return name; }
    public UUID getParentId() { return parentId; }
    public boolean isActive() { return isActive; }
    public boolean isCustom() { return isCustom; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
}
